use vstd::prelude::*;

verus! {

/// flipud takes a vector of f32 and returns a new vector
/// with the elements in reverse order.
/// 
/// Ensures:
///   - The result has the same length as the input.
///   - For every index i in [0, n), result[i] == m[n - 1 - i].
fn flipud(m: Vec<f32>) -> (result: Vec<f32>)
    ensures
        result.len() == m.len(),
        forall |i: usize| i < result.len() ==> result[i] == m[m.len() - 1 - i],
{
    let n = m.len();
    let mut result: Vec<f32> = Vec::new();
    // Pre-allocate to avoid repeated reallocations
    result.reserve(n);

    // We'll build result by pushing elements
    // starting from the end of `m` down to 0.
    let mut i: usize = n;
    while i > 0
        invariant
            // i always stays between 0 and n
            i <= n,
            // we've pushed exactly (n - i) elements so far
            result.len() + i == n,
            // and for each pushed index j, result[j] == m[n - 1 - j]
            forall |j: usize| j < result.len() ==>
                result[j] == m[n - 1 - j],
        decreases i,
    {
        i -= 1;
        result.push(m[i]);
    }

    result
}

} // end verus! 

fn main() {
    // A quick sanity check at runtime (not verified):
    let v = vec![1.0f32, 2.0, 3.0, 4.0];
    let r = flipud(v.clone());
    // Expect [4.0, 3.0, 2.0, 1.0]
    assert_eq!(r, vec![4.0f32, 3.0, 2.0, 1.0]);
}